  function bindFlashSwipe() {
    const wrap = flashPage.querySelector("#primaryFlashCardWrap");
    const card2 = flashPage.querySelector("#primaryFlashCard");
    if (!wrap || !card2) return;
    if (card2.__flashSwipeBound) return;
    card2.__flashSwipeBound = true;
    let startX = 0;
    let startY = 0;
    let dxLive = 0;
    let dyLive = 0;
    let tracking = false;
    let suppressClick = false;
    card2.addEventListener("click", () => {
      console.log("[flash] card click");
      if (suppressClick) return;
      card2.classList.toggle("is-flipped");
    });
    const resetCard = () => {
      wrap.style.transition = "transform 180ms ease";
      wrap.style.transform = "translateX(0px) rotate(0deg)";
      setTimeout(() => {
        wrap.style.transition = "";
      }, 200);
    };
    const flyOut = (dir, cb) => {
      const off = dir * Math.max(320, window.innerWidth);
      wrap.style.transition = "transform 180ms ease";
      wrap.style.transform = `translateX(${off}px) rotate(${dir * 10}deg)`;
      setTimeout(() => {
        wrap.style.transition = "";
        wrap.style.transform = "translateX(0px) rotate(0deg)";
        if (typeof cb === "function") cb();
      }, 190);
    };
    card2.addEventListener(
      "touchstart",
      (e) => {
        const t8 = e.touches?.[0];
        if (!t8) return;
        tracking = true;
        startX = t8.clientX;
        startY = t8.clientY;
        dxLive = 0;
        dyLive = 0;
        suppressClick = false;
        wrap.style.transition = "";
      },
      { passive: false },
    );
    card2.addEventListener(
      "touchmove",
      (e) => {
        if (!tracking) return;
        e.preventDefault();
        const t8 = e.touches?.[0];
        if (!t8) return;
        const dx = t8.clientX - startX;
        const dy = t8.clientY - startY;
        if (Math.abs(dx) > 8 || Math.abs(dy) > 8) suppressClick = true;
        dxLive = dx;
        dyLive = dy;
        if (Math.abs(dx) >= Math.abs(dy)) {
          const rot = Math.max(-12, Math.min(12, dx / 18));
          wrap.style.transform = `translateX(${dx}px) rotate(${rot}deg)`;
        }
      },
      { passive: false },
    );
    card2.addEventListener("touchend", () => {
      if (!tracking) return;
      tracking = false;
      const unlockClick = () => (suppressClick = false);
      setTimeout(unlockClick, 250);
      if (dyLive < -90) {
        card2.classList.toggle("is-flipped");
        resetCard();
        return;
      }
      if (dxLive > 90) {
        flyOut(1, () => submitFlashAnswer(true));
        return;
      }
      if (dxLive < -90) {
        flyOut(-1, () => submitFlashAnswer(false));
        return;
      }
      resetCard();
    });
    let pointerId = null;
    card2.addEventListener("pointerdown", (event) => {
      if (event.pointerType === "touch" || event.button !== 0) return;
      pointerId = event.pointerId;
      tracking = true;
      startX = event.clientX;
      startY = event.clientY;
      dxLive = 0;
      dyLive = 0;
      suppressClick = false;
      wrap.style.transition = "";
      card2.setPointerCapture?.(pointerId);
    });
    card2.addEventListener("pointermove", (event) => {
      if (!tracking || event.pointerId !== pointerId) return;
      dxLive = event.clientX - startX;
      dyLive = event.clientY - startY;
      if (Math.abs(dxLive) > 8 || Math.abs(dyLive) > 8) suppressClick = true;
      if (Math.abs(dxLive) >= Math.abs(dyLive)) {
        event.preventDefault();
        const rot = Math.max(-12, Math.min(12, dxLive / 18));
        wrap.style.transform = `translateX(${dxLive}px) rotate(${rot}deg)`;
      }
    });
    const finishPointerSwipe = (event) => {
      if (!tracking || event.pointerId !== pointerId) return;
      tracking = false;
      card2.releasePointerCapture?.(pointerId);
      pointerId = null;
      setTimeout(() => (suppressClick = false), 250);
      if (dyLive < -90) {
        card2.classList.toggle("is-flipped");
        resetCard();
      } else if (dxLive > 90) {
        flyOut(1, () => submitFlashAnswer(true));
      } else if (dxLive < -90) {
        flyOut(-1, () => submitFlashAnswer(false));
      } else {
        resetCard();
      }
    };
    card2.addEventListener("pointerup", finishPointerSwipe);
    card2.addEventListener("pointercancel", finishPointerSwipe);
    flashSwipeBound = true;
  }
