(function () {
  const IMAGES_BASE = "images/";
  const PREFIX = "car_";
  const EXT = ".webp";
  const eyesRoot =
    document.getElementById("eyesCatalogPage") ||
    document.getElementById("eyesPage") ||
    document.getElementById("eyes") ||
    document;
  const cards = eyesRoot.querySelectorAll(
    "[data-card-id], [data-key], [data-image-name], .eyes-card, .card",
  );
  function normalizeName(s) {
    return (s || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "")
      .trim();
  }
  function deriveNameFromTitle(card2) {
    const titleEl2 =
      card2.querySelector("[data-title]") ||
      card2.querySelector(".card-title") ||
      card2.querySelector("h1, h2, h3, h4, h5, h6");
    return titleEl2 ? titleEl2.textContent : "";
  }
  function chosenBaseName(card2) {
    const explicit = card2.getAttribute("data-image-name");
    if (explicit) {
      const hasPrefix = explicit.startsWith(PREFIX);
      const hasExt = explicit.toLowerCase().endsWith(EXT);
      if (hasPrefix && hasExt) return explicit;
      const base = hasPrefix ? explicit.slice(PREFIX.length) : explicit;
      const normalized = normalizeName(
        base.replace(new RegExp(EXT + "$", "i"), ""),
      );
      return PREFIX + normalized + EXT;
    }
    const keyish =
      card2.getAttribute("data-card-id") || card2.getAttribute("data-key");
    if (keyish) return PREFIX + normalizeName(keyish) + EXT;
    const title = deriveNameFromTitle(card2);
    return PREFIX + normalizeName(title) + EXT;
  }
  function applyImage(card2, filename) {
    const fullPath = IMAGES_BASE + filename;
    const imgEl = card2.querySelector("[data-card-img], .card-img, img");
    if (imgEl && imgEl.tagName === "IMG") {
      imgEl.setAttribute("src", fullPath);
      imgEl.setAttribute(
        "alt",
        imgEl.getAttribute("alt") ||
          filename.replace(/^car_/, "").replace(/\.webp$/i, ""),
      );
      return;
    }
    const thumbEl = card2.querySelector(".card-thumb, [data-thumb]");
    if (thumbEl) {
      thumbEl.style.backgroundImage = `url("${fullPath}")`;
      thumbEl.style.backgroundSize = thumbEl.style.backgroundSize || "cover";
      thumbEl.style.backgroundPosition =
        thumbEl.style.backgroundPosition || "center";
      thumbEl.style.backgroundRepeat = "no-repeat";
      return;
    }
    card2.style.backgroundImage = `url("${fullPath}")`;
    card2.style.backgroundSize = card2.style.backgroundSize || "cover";
    card2.style.backgroundPosition = card2.style.backgroundPosition || "center";
    card2.style.backgroundRepeat = "no-repeat";
  }
  function processCards() {
    cards.forEach((card2) => {
      const filename = chosenBaseName(card2);
      if (!/^car_[a-z0-9]+\.webp$/i.test(filename)) return;
      applyImage(card2, filename);
    });
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", processCards);
  } else {
    processCards();
  }
})();
